class Solution {public int[] solve(int n,int[][] edges){int[] d=new int[n],ways=new int[n];Arrays.fill(d,-1);if(n==0)return ways;ArrayList<ArrayList<Integer>> adj=new ArrayList<>();for(int i=0;i<n;i++)adj.add(new ArrayList<>());for(int[] e:edges)adj.get(e[0]).add(e[1]);ArrayDeque<Integer>q=new ArrayDeque<>();q.add(0);d[0]=0;ways[0]=1;while(!q.isEmpty()){int u=q.remove();for(int v:adj.get(u)){if(d[v]<0){d[v]=d[u]+1;q.add(v);}if(d[v]==d[u]+1)ways[v]=(ways[v]+ways[u])%1000000007;}}return ways;}}